#!/usr/bin/env bash
set -euo pipefail

# Emit every Go package this module owns, one per line.
# Usage: go_packages.sh [project_root]
#
# build/ is Wails' generated build assets (platform entrypoints, dependency
# installers), regenerated by `wails3 update build-assets`, so nothing here
# formats, lints, or tests it.

PROJECT_ROOT="${1:-$(pwd)}"

cd "${PROJECT_ROOT}"

packages="$(go list -e ./...)"

if [ -z "${packages}" ]; then
  echo "go_packages.sh: go list named no packages under ${PROJECT_ROOT}" >&2
  exit 1
fi

printf '%s\n' "${packages}" | grep -v '^github.com/primandproper/docent/build\(/\|$\)'
